if _forget_ids:
    # Also collect the forget tool's own IDs so we can remove
    # its call+result from messages (sentinel residue cleanup).
    _forget_self_ids: set[str] = set()
    for (tc, args_str, dedup_key), raw in zip(pending, exec_results):
        if isinstance(raw, BaseException):
            continue
        tool_result, _, _ = raw
        if isinstance(tool_result, str) and tool_result.startswith("__FORGET__:"):
            _forget_self_ids.add(tc.id)

    _all_remove_ids = _forget_ids | _forget_self_ids

    # Remove tool result messages with matching tool_call_id
    messages[:] = [
        m for m in messages
        if not (
            m.get("role") == "tool"
            and m.get("tool_call_id") in _all_remove_ids
        )
    ]
    # Remove matching tool_calls from ALL assistant messages
    # (not just the last one — the forgotten call may be in an
    # earlier assistant message when forget is called later)
    for i in range(len(messages) - 1, -1, -1):
        m = messages[i]
        if m.get("role") == "assistant" and m.get("tool_calls"):
            m["tool_calls"] = [
                tc for tc in m["tool_calls"]
                if tc.get("id") not in _all_remove_ids
            ]
            if not m["tool_calls"]:
                if not m.get("content"):
                    # No content, no tool_calls → remove entirely
                    messages.pop(i)
                else:
                    # Has content but no tool_calls → remove the
                    # empty tool_calls key to avoid confusing the LLM
                    del m["tool_calls"]
    logger.info(
        "tool_loop: forget deleted {} tool call(s): {}",
        len(_forget_ids), ", ".join(_forget_names),
    )

